/* Complete, standalone task statements. Stable IDs preserve existing progress. */
const QUESTION_PROMPTS={"core-1": "Пусть X и Y — непустые множества, а P(x,y) — высказывание при x∈X и y∈Y. Запишите логическое отрицание утверждения: для каждого x∈X существует y∈Y, для которого P(x,y) истинно. Порядок выбора переменных должен быть сохранён.", "core-2": "Дано множество действительных чисел X=[−2,+∞). Опишите все его действительные нижние грани и определите, существуют ли у него действительные верхние грани. Требуется множество всех границ, а не только inf X или sup X.", "core-3": "Дано X={1−1/n : n∈ℕ, n≥1}. Найдите inf X и sup X и укажите, какие из них достигаются: существуют ли min X и max X?", "core-4": "Даны X=(0,2) и Y=[−1,3]. Их сумма определяется как X+Y={x+y : x∈X, y∈Y}. Найдите sup(X+Y), учитывая все допустимые пары x,y.", "core-5": "Теорема утверждает: каждое непустое, ограниченное сверху подмножество ℝ имеет действительную точную верхнюю грань. Почему из этой теоремы нельзя удалить условие непустоты? Исследуйте множество всех действительных верхних граней пустого множества.", "core-6": "О действительной последовательности (xₙ) известно только, что у неё ровно одна конечная предельная точка a: подпоследовательность с пределом a существует, а с иным конечным пределом — нет. Ограниченность (xₙ) не предполагается. Достаточно ли этих условий, чтобы заключить xₙ→a?", "core-7": "Рассматриваются действительные последовательности при n∈ℕ, n≥1. Каждый предложенный ответ задаёт отдельную последовательность. Выберите ту, которая ограничена, но не имеет конечного предела при n→∞.", "core-8": "Пусть (xₙ) — действительная последовательность и limₙ→∞ xₙ=−3. Какое из предложенных свойств обязательно выполняется для всех n>N при некотором N? О первых членах последовательности дополнительных предположений нет.", "core-9": "Пусть (xₙ) — действительная последовательность, для каждого n∈ℕ, n≥1 выполнено 0<xₙ<1 и существует конечный предел a=limₙ→∞ xₙ. Какое утверждение об a обязательно следует из этих условий для любой такой последовательности? Нужно установить гарантированное ограничение, а не угадать возможное значение a.", "core-10": "Для n∈ℕ, n≥1 положим uₙ=sin(n)/n; аргумент синуса измеряется в радианах. Вычислите limₙ→∞ uₙ, обосновав ответ оценками сверху и снизу.", "core-11": "Действительная последовательность задана для каждого k≥1 равенствами x₂ₖ=0 и x₂ₖ₋₁=k. Является ли она бесконечно большой по модулю, то есть выполняется ли |xₙ|→+∞? Не смешивайте это условие с неограниченностью.", "core-12": "Пусть (αₙ) — действительная бесконечно малая последовательность: αₙ→0 при n→∞. Что обязательно можно утверждать о пределе последовательности βₙ=|αₙ|? Равенство отдельных членов нулю не предполагается.", "core-13": "Для n∈ℕ, n≥1 задана последовательность xₙ=(3n+2)/(2n−1). Вычислите её конечный предел при n→∞ и проверьте условие применения правила частного.", "core-14": "Дана последовательность xₙ=2−1/n, n∈ℕ, n≥1. Найдите limₙ→∞ xₙ; при обосновании можно использовать её монотонность и ограниченность либо определение предела.", "core-15": "Разложите многочлен (x+1)⁵ по степеням x. Каков числовой коэффициент именно при x²? Требуется коэффициент, а не всё слагаемое с x².", "core-16": "Для каждого n∈ℕ, n≥1 задан открытый интервал Iₙ=(0,1/n). Почему общее пересечение всех Iₙ пусто, несмотря на вложенность интервалов и стремление их длин к нулю? Проверьте также, выполнены ли условия леммы о вложенных отрезках.", "core-17": "Рассмотрите действительную последовательность xₙ=sin n, n≥1, с аргументом в радианах. Какое из предложенных утверждений обязательно гарантируется её ограниченностью и теоремой Больцано–Вейерштрасса? Сходимость всей последовательности не предполагается.", "core-18": "Пусть Hₙ=1+1/2+…+1/n при n≥1. Какое рассуждение по критерию Коши доказывает отсутствие конечного предела у (Hₙ)? Обоснуйте существование фиксированного ε₀>0 и сколь угодно поздних пар индексов с |Hₘ−Hₙ|≥ε₀.", "core-19": "Пусть f(x)=sin(1/x) при x∈ℝ, x≠0; углы измеряются в радианах. Какую пару последовательностей ненулевых аргументов xₙ→0 и yₙ→0 можно использовать по Гейне, чтобы опровергнуть существование двустороннего предела f при x→0? Проверьте пределы обоих образов f(xₙ), f(yₙ).", "core-20": "Пусть a∈ℝ, функция f определена в некоторой проколотой окрестности a и limₓ→a f(x)=5. Какое из предложенных свойств обязательно выполняется для всех x с 0<|x−a|<δ при некотором δ>0? Значение f(a) может быть не задано и на вывод не влияет.", "core-21": "Пусть f(x)=(x²+1)/(x+1), x∈ℝ, x≠−1. Вычислите limₓ→2 f(x), предварительно проверив ненулевой предел знаменателя.", "core-22": "При x≠0 задано f(x)=sin x/x, углы измеряются в радианах. Какое значение f(0)=c нужно назначить, чтобы доопределённая функция была непрерывна в нуле?", "core-23": "Дана действительная функция h(x)=sin(x²), x∈ℝ; углы измеряются в радианах. Непрерывна ли она в каждой точке ℝ? Обоснуйте ответ теоремой о композиции, проверив непрерывность внутренней и внешней функций.", "core-24": "Дано f(x)=1/(x−2) на её естественной действительной области определения. Укажите все точки ℝ, в которых исходная функция определена и непрерывна; доопределять её в исключённых точках не требуется.", "core-25": "Вычислите двусторонний предел limₓ→0 sin(5x)/tg(2x) по области определения дроби. Все углы измеряются в радианах. Обоснуйте применение первого замечательного предела.", "core-26": "Вычислите двусторонний предел limₓ→0 (1+3x)^(2/x). Рассматривается действительная степень при x≠0 и 1+3x>0. Используйте второй замечательный предел или его следствия.", "core-27": "На ℝ задана функция Дирихле: D(x)=1 при рациональном x и D(x)=0 при иррациональном x. Пусть a∈ℝ — любая фиксированная точка. Какое из предложенных ε₀>0 позволяет опровергнуть критерий Коши: в каждой проколотой δ-окрестности a найти x,y с |D(x)−D(y)|≥ε₀?", "core-28": "Для f(x)=(2x²+1)/(x²−3) на естественной действительной области определения вычислите limₓ→+∞ f(x). Все преобразования выполняйте при достаточно больших x, где знаменатель ненулевой.", "core-29": "Вычислите двусторонний предел limₓ→0 (1−cos(3x))/x² при x≠0. Углы измеряются в радианах. Можно использовать первый замечательный предел или эквивалентность 1−cos t∼t²/2 при t→0.", "core-30": "Функция f(x)=1/x непрерывна, но неограниченна на E=(0,1]. Почему это не является контрпримером к теореме об ограниченности функции, непрерывной на замкнутом отрезке? Назовите нарушенное условие именно этой теоремы.", "core-31": "Дана функция f(x)=x² на замкнутом отрезке [−2,1]. Найдите её наименьшее и наибольшее значения на всём отрезке и укажите точки, где эти значения достигаются.", "core-32": "Для f(x)=x³+x−1 докажите или опровергните существование хотя бы одного c∈(0,1) с f(c)=0. Требуется ответ о существовании корня по непрерывности и значениям на концах, а не его точное вычисление.", "core-33": "Пусть f:[0,1]→ℝ непрерывна на всём отрезке, f(0)=−2 и f(1)=5. Обязательно ли существует хотя бы одна внутренняя точка c∈(0,1), для которой f(c)=3? Единственность такой точки не утверждается.", "core-34": "Рассмотрите f:[0,+∞)→[0,+∞), f(x)=x². Укажите область определения и формулу обратной функции g и определите, непрерывна ли g на всей своей области, включая её левый конец.", "core-35": "На ℝ задана функция f(x)=−1 при x<0, f(0)=0 и f(x)=1 при x>0. Определите вид её разрыва в нуле и величину скачка f(0+0)−f(0−0). В обосновании предварительно вычислите оба односторонних предела.", "core-36": "Для f(x)=x² на E=(0,1) используется точный модуль непрерывности ω(δ)=sup{|f(x)−f(y)|: x,y∈E, |x−y|<δ}, δ>0. Найдите ω(1/2). Требуется супремум разностей, который не обязан достигаться на допустимой паре.", "core-37": "Пусть f(x)=sin(1/x) и E=[1/2,1]. Является ли ограничение f на E равномерно непрерывным? Углы измеряются в радианах; рассуждение должно относиться именно к этому отрезку, а не ко всей области x>0.", "core-38": "Докажите по определению Коши, что limₓ→3 x²=9. Для произвольного ε>0 выберите из предложенных формул положительный радиус δ(ε), который для всех действительных x обеспечивает импликацию 0<|x−3|<δ ⇒ |x²−9|<ε.", "core-39": "Пусть f:E→ℝ, x₀ — предельная точка E и A∈ℝ. Что требуется сделать для доказательства limₓ→x₀ f(x)=A по Гейне? Аргументы последовательностей должны лежать в E, отличаться от x₀ и стремиться к x₀; выбор одной специальной последовательности сам по себе не доказывает предел.", "legacy-sets-1": "Дан полуинтервал X=(−3,4]⊂ℝ. Найдите inf X, sup X и определите, существуют ли min X и max X; если существуют, укажите их значения.", "legacy-sets-2": "Дано множество X={2−1/n : n∈ℕ, n≥1}. Найдите его точную верхнюю грань sup X и установите, достигается ли она, то есть существует ли max X.", "legacy-sets-3": "Пусть X={x∈ℝ : x²<9}. Укажите sup X и определите, существует ли max X. Граничные точки, не удовлетворяющие строгому условию, включать в X нельзя.", "legacy-sets-4": "Рассмотрите X=[1,+∞)⊂ℝ. Определите отдельно, ограничено ли X снизу и ограничено ли оно сверху действительными числами.", "legacy-sets-5": "Пусть X=(0,1). Какой набор из предложенных условий достаточен, чтобы доказать именно sup X=1? Нужно проверить и свойство верхней границы, и невозможность её уменьшить.", "legacy-sets-6": "Дано X={1/n : n∈ℕ, n≥1}. Найдите inf X и определите, достигается ли эта грань, то есть существует ли min X.", "legacy-sets-7": "Дано конечное множество X={−2,0,5}⊂ℝ. Какое предложенное утверждение верно описывает его точную верхнюю грань и максимум?", "legacy-sets-8": "Пусть X⊂ℝ и A∈ℝ — верхняя граница X: для каждого x∈X выполнено x≤A. Что обязательно верно о числе A′∈ℝ, если A′>A? Точность границы A не предполагается.", "legacy-seq-1": "Пусть (xₙ) — действительная последовательность, a∈ℝ. Какое утверждение с кванторами равносильно определению limₙ→∞ xₙ=a? Номер N может зависеть от ε, а оценка должна выполняться для всех n>N.", "legacy-seq-2": "Для xₙ=(3n+1)/(n+2), n∈ℕ, n≥1, вычислите limₙ→∞ xₙ.", "legacy-seq-3": "При проверке предела xₙ=1/n→0, n≥1, требуется оценка |xₙ|<0,01 для каждого n>N. Какое из предложенных целых N достаточно для выполнения именно этой строгой оценки?", "legacy-seq-4": "Дана действительная последовательность xₙ=(−1)ⁿ при n≥1. Имеет ли она предел при n→∞ и какие у неё конечные предельные точки, то есть пределы сходящихся подпоследовательностей?", "legacy-seq-5": "Пусть действительная последовательность (xₙ) сходится к конечному a∈ℝ. Какое свойство обязательно выполняется для всей последовательности, включая конечное число начальных членов?", "legacy-seq-6": "Дана последовательность xₙ=5+1/n, n∈ℕ, n≥1. Вычислите её предел при n→∞.", "legacy-seq-7": "Каждый предложенный ответ задаёт действительную последовательность при n∈ℕ, n≥1. Какая из них имеет предел 0 при n→∞? Проверяется предел всей последовательности.", "legacy-seq-8": "Можно ли для одной действительной последовательности одновременно выполнить определения конечных пределов xₙ→a и xₙ→b при a≠b? Выберите вывод, который следует из теоремы единственности.", "legacy-seqops-1": "Пусть xₙ→2 и yₙ→−5 при n→∞, обе последовательности действительные. Вычислите limₙ→∞(xₙ+yₙ).", "legacy-seqops-2": "Для n∈ℕ, n≥1, задано xₙ=(4n²+3)/(2n²−n). Вычислите limₙ→∞ xₙ; исходный знаменатель при этих n ненулевой.", "legacy-seqops-3": "Пусть действительная последовательность xₙ→3 при n→∞. Вычислите limₙ→∞(xₙ²−1), используя арифметику конечных пределов.", "legacy-seqops-4": "Для xₙ=(n+1)/(3n−2), n∈ℕ, n≥1, вычислите limₙ→∞ xₙ.", "legacy-seqops-5": "Пусть xₙ,zₙ,yₙ — действительные последовательности. Начиная с некоторого номера выполнено xₙ≤zₙ≤yₙ, причём xₙ→4 и yₙ→4. Какой вывод о пределе zₙ обязательно следует из этих условий?", "legacy-seqops-6": "Для действительных последовательностей (aₙ),(bₙ) выполнено aₙ<bₙ при каждом n≥1, но обе имеют предел 2. Как следует сравнить их пределы? Определите, обязано ли строгое неравенство между членами сохраняться для пределов.", "legacy-seqops-7": "Для n∈ℕ, n≥1, вычислите limₙ→∞(1/n+1/n²). Обоснуйте результат свойством суммы двух бесконечно малых последовательностей.", "legacy-seqops-8": "Пусть xₙ→a и yₙ→b — конечные пределы действительных последовательностей. Какое дополнительное условие на b гарантирует, что частное xₙ/yₙ определено в хвосте и его предел можно вычислить как a/b?", "legacy-monotone-1": "Какого из предложенных наборов свойств действительной последовательности достаточно, чтобы гарантировать существование её конечного предела по теореме о монотонной ограниченной последовательности?", "legacy-monotone-2": "Дана последовательность xₙ=−n при n∈ℕ, n≥1. Определите направление её монотонности и наличие нижней действительной границы.", "legacy-monotone-3": "Речь идёт о критерии Коши конечной сходимости действительной последовательности. Какие величины должны быть близки друг к другу с любой заданной точностью после некоторого номера? Предполагаемый предел заранее не задан.", "legacy-monotone-4": "Пусть (xₙ) — ограниченная действительная последовательность. Какое заключение обязательно гарантирует теорема Больцано–Вейерштрасса? Сходимость всей последовательности и её монотонность дополнительно не предполагаются.", "legacy-monotone-5": "Дана последовательность xₙ=1−1/n, n∈ℕ, n≥1. Определите её монотонность и предел при n→∞.", "legacy-monotone-6": "Пусть действительная последовательность (xₙ) не убывает и множество её членов имеет конечный sup{xₙ:n≥1}=6. Чему равен limₙ→∞ xₙ?", "legacy-monotone-7": "Может ли ограниченная действительная последовательность не иметь конечного предела? Если да, предложенный ответ должен содержать допустимый контрпример; его формула служит примером, а не дополнительным условием о произвольной последовательности.", "legacy-monotone-8": "Пусть члены действительной последовательности удовлетворяют рекуррентному равенству, и для нахождения предполагаемого предела хотят перейти в нём к пределу. Что необходимо предварительно обосновать, чтобы такой переход не опирался на недоказанное предположение?", "legacy-functionlim-1": "Пусть f:E→ℝ и x₀ — предельная точка E. Почему в определении limₓ→x₀ f(x) проверяются аргументы из E с 0<|x−x₀|<δ, то есть сама точка x=x₀ исключается?", "legacy-functionlim-2": "Пусть f(x)=(x²−4)/(x−2) при x∈ℝ, x≠2. Вычислите двусторонний предел f(x) при x→2. Доопределение функции в точке 2 для вычисления предела не требуется.", "legacy-functionlim-3": "Требуется доказать по Коши limₓ→3 x²=9. Какое предложенное тождество позволяет выразить ошибку |x²−9| через расстояние |x−3| и начать подбор δ для произвольного ε>0?", "legacy-functionlim-4": "Пусть f:E→ℝ, а x₀ — предельная точка E. Как с помощью последовательностей аргументов из E, отличных от x₀ и стремящихся к x₀, достаточно опровергнуть существование единого конечного предела f при x→x₀ по Гейне?", "legacy-functionlim-5": "На ℝ задано f(x)=7 при x≠0 и f(0)=−100. Вычислите limₓ→0 f(x). Требуется предел, а не значение функции в самой точке 0.", "legacy-functionlim-6": "Для f(x)=3x+2, x∈ℝ, вычислите limₓ→1 f(x).", "legacy-functionlim-7": "Функция f(x)=sin(1/x) задана при x∈ℝ, x≠0; углы измеряются в радианах. Существует ли её двусторонний предел при x→0? Ответ должен учитывать все допустимые способы приближения, а не один выбранный путь.", "legacy-functionlim-8": "Пусть функции f и g определены в некоторой проколотой окрестности a∈ℝ и имеют конечные пределы limₓ→a f(x)=2, limₓ→a g(x)=−1. Вычислите limₓ→a(f(x)g(x)).", "legacy-onesided-1": "Дано f(x)=|x|/x при x≠0. Найдите отдельно limₓ→0− f(x) и limₓ→0+ f(x), сохраняя в ответе порядок «слева, справа».", "legacy-onesided-2": "Пусть f определена по обе стороны от a в некоторой проколотой окрестности. Какое условие на левый и правый пределы необходимо и достаточно для существования конечного двустороннего предела f при x→a?", "legacy-onesided-3": "Для f(x)=1/x, x≠0, определите предел при x→0 справа, то есть только по положительным x. Укажите знак бесконечности.", "legacy-onesided-4": "Пусть sgn x=−1 при x<0, sgn 0=0 и sgn x=1 при x>0. Существует ли конечный двусторонний предел этой функции при x→0? Обоснуйте ответ сравнением односторонних пределов.", "legacy-onesided-5": "В критерии Коши существования конечного предела f(x) при x→x₀ функция задана в проколотой окрестности x₀. Какие именно значения функции сравниваются, и где должны лежать оба аргумента?", "legacy-onesided-6": "Для f(x)=1/x, x≠0, определите предел при x→0 слева, то есть только по отрицательным x. Укажите знак бесконечности.", "legacy-onesided-7": "Пусть функция определена по обе стороны от a, и оба её односторонних предела конечны и равны 4. Какой вывод о двустороннем пределе при x→a обязательно следует? Значение f(a) не задаётся.", "legacy-onesided-8": "Пусть f определена по обе стороны от a, limₓ→a− f(x)=2 и limₓ→a+ f(x)=3. Существует ли единый конечный двусторонний предел при x→a?", "legacy-remarkable-1": "Вычислите limₓ→0 sin(4x)/(2x) при x≠0. Все углы измеряются в радианах.", "legacy-remarkable-2": "Вычислите limₓ→0 sin(9x)/(3x) при x≠0. Все углы измеряются в радианах.", "legacy-remarkable-3": "Вычислите limₓ→+∞(1+1/x)ˣ по действительным x. При достаточно больших x основание положительно, и степень рассматривается в действительном смысле.", "legacy-remarkable-4": "Вычислите limₓ→+∞(1+5/x)ˣ по действительным x с положительным основанием степени.", "legacy-remarkable-5": "Вычислите limₓ→0(1+2x)^(1/x) по x≠0, 1+2x>0. Используйте второй замечательный предел или его следствие.", "legacy-remarkable-6": "Вычислите limₓ→0(1−cos x)/x² при x≠0. Углы измеряются в радианах.", "legacy-remarkable-7": "В какой единице необходимо измерять аргумент x, чтобы справедливо было равенство limₓ→0 sin x/x=1? Рассматривается обычная тригонометрическая функция синуса.", "legacy-remarkable-8": "Вычислите limₓ→0(1+3x)^(4/x) по x≠0, 1+3x>0. Рассматривается действительная степень.", "legacy-infinite-1": "Пусть α(x),β(x) — бесконечно малые при x→a, причём β(x)≠0 в рассматриваемой проколотой области. Какое условие на предел отношения α(x)/β(x) является определением записи α(x)=o(β(x))?", "legacy-infinite-2": "При x→0 сравните бесконечно малую sin x с функциями, указанными в ответах. Какая предложенная эквивалентность верна, то есть отношение левой и правой частей стремится к 1? Углы измеряются в радианах.", "legacy-infinite-3": "При x→0, x≠0, найдите предложенный эквивалент бесконечно малой 1−cos x. Требуется функция, отношение к которой стремится к 1; углы измеряются в радианах.", "legacy-infinite-4": "Пусть α(x)→0 при x→a и α(x)≠0 для всех допустимых аргументов достаточно близко к a. Что обязательно происходит с модулем 1/α(x) при x→a? Постоянный знак α не предполагается.", "legacy-infinite-5": "Для x≠0 вычислите limₓ→0(eˣ−1)/x, где e — основание натуральной экспоненты.", "legacy-infinite-6": "Для f(x)=(7x²+1)/(2x²−x) на естественной действительной области определения вычислите limₓ→+∞ f(x).", "legacy-infinite-7": "При x→0, x≠0, найдите из предложенных ответов эквивалент бесконечно малой α(x)=x+x². Эквивалентность проверяется пределом отношения, равным 1.", "legacy-infinite-8": "В какой из предложенных ситуаций нельзя без дополнительного анализа заменять отдельные бесконечно малые эквивалентами? Особое внимание уделите возможному сокращению главных членов, а не только пределу каждого слагаемого.", "legacy-continuity-1": "Пусть x₀ принадлежит области f, функция определена в окрестности x₀ и имеет конечный предел при x→x₀. Какое равенство необходимо и достаточно для её непрерывности в x₀?", "legacy-continuity-2": "Пусть f:[−2,3]→ℝ непрерывна на всём замкнутом отрезке. Какое из предложенных утверждений о её ограниченности и достижении крайних значений обязательно верно?", "legacy-continuity-3": "Пусть f:[0,2]→ℝ непрерывна, f(0)=−3 и f(2)=5. Какое утверждение о существовании внутренней точки c∈(0,2), где f(c)=0, обязательно следует из теоремы о переходе через нуль?", "legacy-continuity-4": "Функция f(x)=1/x непрерывна на E=(0,1]. Почему к ней на E нельзя применить теорему Вейерштрасса об ограниченности и достижении экстремумов на отрезке? Назовите нарушенное условие на область.", "legacy-continuity-5": "Рассмотрите многочлен f(x)=x⁵−3x+1 как действительную функцию на ℝ. Какое утверждение о её непрерывности верно?", "legacy-continuity-6": "Пусть a<b. Какой из предложенных наборов условий на действительную функцию f достаточен для применения теоремы о переходе через нуль и гарантирует существование корня в открытом интервале (a,b)?", "legacy-continuity-7": "Пусть f непрерывна и строго возрастает на некотором действительном промежутке I. Что можно гарантировать о числе решений уравнения f(x)=0 в I, если значения на концах и наличие смены знака дополнительно не заданы?", "legacy-continuity-8": "Пусть f:[a,b]→ℝ непрерывна и a<b. Какое утверждение о достижении значений, лежащих между f(a) и f(b), обязательно следует из теоремы о промежуточных значениях? Монотонность f не предполагается.", "legacy-breaks-1": "Пусть f определена в проколотой окрестности x₀ и существует конечный предел limₓ→x₀ f(x)=L, но значение f(x₀) не задано. Как называется разрыв исходной функции, который можно устранить назначением одного значения в x₀?", "legacy-breaks-2": "Рассмотрите f(x)=1/x при x≠0. К какому виду относится разрыв в x=0, если классифицировать его по односторонним пределам?", "legacy-breaks-3": "Функция определена в проколотой окрестности x₀ и имеет конечные односторонние пределы f(x₀−0)=−2, f(x₀+0)=4. Определите вид разрыва и скачок f(x₀+0)−f(x₀−0). Значение в x₀ на скачок не влияет.", "legacy-breaks-4": "При x≠0 задано f(x)=sin x/x, аргумент измеряется в радианах, значение в нуле не задано. К какому виду относится разрыв в 0 и можно ли устранить его доопределением в этой точке?", "legacy-breaks-5": "При x≠0 задано f(x)=sin(1/x), углы измеряются в радианах. Существует ли предел при x→0 и чем обусловлено его отсутствие, если он не существует?", "legacy-breaks-6": "Функция определена в окрестности 0, f(0)=7, а оба односторонних предела в 0 равны 2. Определите вид разрыва в 0 и возможность устранить его изменением только f(0).", "legacy-breaks-7": "Пусть известно, что функция не является непрерывной в x₀, но вид разрыва не установлен. Какие предельные величины необходимо исследовать в первую очередь для его классификации?", "legacy-breaks-8": "Функция определена в проколотой окрестности x₀. Известно, что хотя бы один односторонний предел при приближении к x₀ равен +∞ или −∞. К какому роду относится такой разрыв?", "legacy-uniform-1": "Пусть f:E→ℝ. В чём состоит ключевое требование к радиусу δ в определении равномерной непрерывности на всём E, в отличие от непрерывности в одной выбранной точке?", "legacy-uniform-2": "Пусть f(x)=3x+1 на всей ℝ, ε>0 произвольно. Какой из предложенных радиусов δ(ε)>0 обеспечивает для любых x,y∈ℝ импликацию |x−y|<δ ⇒ |f(x)−f(y)|<ε?", "legacy-uniform-3": "Пусть f:[a,b]→ℝ непрерывна, где a≤b — конечные действительные числа. Какое свойство равномерной непрерывности на этом отрезке обязательно следует из теоремы Кантора?", "legacy-uniform-4": "Вычислите limₓ→0(√(1+x)−1)/x по действительным x≥−1, x≠0. Можно использовать умножение на сопряжённое выражение.", "legacy-uniform-5": "В определении непрерывности f в каждой точке x₀ области радиус выбирается после задания ε>0. Что означает возможность зависимости δ=δ(ε,x₀), и почему это ещё не даёт равномерного выбора одного δ для всей области?", "legacy-uniform-6": "Какой из предложенных наборов условий на действительную функцию и её область достаточен для применения теоремы Кантора о равномерной непрерывности?", "legacy-uniform-7": "При вычислении предела встретилась разность √A(x)−√B(x), где A(x),B(x)≥0 и сумма корней ненулевая в рассматриваемой проколотой области. Какое алгебраическое преобразование позволяет заменить эту разность выражением с A(x)−B(x)?", "legacy-uniform-8": "Пусть f:E→ℝ равномерно непрерывна на E. Какое утверждение о непрерывности f в каждой отдельной точке E относительно этой области обязательно верно?", "legacy-logic-1": "Пусть X — множество и P(x) — высказывание для x∈X. Запишите точное логическое отрицание утверждения ∀x∈X: P(x), сохраняя ту же область переменной.", "legacy-logic-2": "Пусть X — множество и P(x) — высказывание для x∈X. Запишите точное логическое отрицание утверждения ∃x∈X: P(x), сохраняя ту же область переменной.", "legacy-logic-3": "Пусть P и Q — высказывания. Какое логическое выражение равносильно отрицанию импликации ¬(P⇒Q)? Требуется отрицание, а не обратное или противоположное утверждение.", "legacy-logic-4": "Как достаточно опровергнуть утверждение ∀x∈ℝ: x²<0? Предложенный способ должен логически доказывать ложность всеобщего утверждения; проверка всех действительных x не требуется.", "legacy-logic-5": "Запишите символами фразу: для любого действительного ε>0 существует действительное δ>0. Сохраните порядок кванторов и ограничения на обе переменные.", "legacy-logic-6": "Пусть P,Q — высказывания. Запишите контрапозицию импликации P⇒Q: утверждение, логически равносильное ей и получаемое одновременным отрицанием и перестановкой сторон.", "legacy-logic-7": "Пусть (xₙ) — действительная последовательность, a∈ℝ и ε>0 фиксированы. Отрицайте утверждение ∃N∈ℕ ∀n>N: |xₙ−a|<ε. Как должны начинаться кванторы у отрицания?", "legacy-logic-8": "Пусть P,Q — высказывания. Какая пара импликаций вместе равносильна эквиваленции P⇔Q?", "legacy-compactness-1": "Пусть действительная последовательность xₙ→a∈ℝ. Возьмём любую её подпоследовательность xₙₖ со строго возрастающими натуральными индексами nₖ. Что обязательно верно о пределе этой подпоследовательности при k→∞?", "legacy-compactness-2": "Для xₙ=(−1)ⁿ, n≥1, укажите все конечные числа, которые могут быть пределами её сходящихся подпоследовательностей.", "legacy-compactness-3": "Пусть (xₙ) — ограниченная действительная последовательность. Какое утверждение о существовании сходящейся подпоследовательности гарантирует теорема Больцано–Вейерштрасса?", "legacy-compactness-4": "Пусть Iₙ=[aₙ,bₙ] — непустые замкнутые отрезки с конечными концами, Iₙ₊₁⊆Iₙ при всех n≥1 и bₙ−aₙ→0. Что можно утверждать о пересечении всех Iₙ?", "legacy-compactness-5": "Как формулируется условие Коши для действительной последовательности (xₙ)? Для каждого ε>0 один номер N должен обеспечивать оценку для всех пар m,n>N; предел заранее не задаётся.", "legacy-compactness-6": "Пусть у действительной последовательности есть две подпоследовательности, одна стремится к a∈ℝ, другая к b∈ℝ, причём a≠b. Какой вывод о сходимости всей исходной последовательности обязательно верен?", "legacy-compactness-7": "Действительная последовательность (xₙ) удовлетворяет условию Коши: ∀ε>0 ∃N ∀m,n>N: |xₙ−xₘ|<ε. Что обязательно следует о её конечной сходимости в ℝ?", "legacy-compactness-8": "Пусть Iₙ — вложенные непустые замкнутые отрезки внутри конечного I₁. Условие стремления их длин к нулю не задаётся. Обязано ли их общее пересечение состоять ровно из одной точки, или оно может содержать больше одной?", "legacy-combinatorics-1": "Вычислите число сочетаний C₆²: количество способов выбрать два элемента из шести различных без учёта порядка выбора.", "legacy-combinatorics-2": "Каково значение 0!, используемое в стандартном определении факториала и формулах числа сочетаний?", "legacy-combinatorics-3": "Разложите (a+b)⁴ по биному Ньютона. Укажите последовательность числовых коэффициентов при a⁴, a³b, a²b², ab³, b⁴ именно в этом порядке.", "legacy-combinatorics-4": "В разложении многочлена (x+1)⁵ по степеням x найдите числовой коэффициент при x².", "legacy-combinatorics-5": "Пусть n,k — целые числа, n≥0 и 0≤k≤n. Какое из предложенных выражений тождественно равно числу сочетаний Cₙᵏ по свойству симметрии?", "legacy-combinatorics-6": "Для n∈ℕ, n≥1, вычислите limₙ→∞(1+3/n)ⁿ. Основание степени положительно; можно использовать второй замечательный предел.", "legacy-combinatorics-7": "Раскройте скобки в многочлене (x+2)³ и приведите подобные слагаемые. Какой из предложенных многочленов тождественно равен исходному для всех x∈ℝ?", "legacy-combinatorics-8": "Пусть n,k — целые числа, n≥2 и 1≤k≤n−1. Какая предложенная формула выражает Cₙᵏ через числа сочетаний с верхним индексом n−1 по тождеству Паскаля?", "legacy-kr-1": "Контрольная, вариант 1, №1. Вычислите двусторонний предел limₓ→2 (x³−12x+16)/(x²−4) по области определения дроби. Эквивалентности и правило Лопиталя не используйте; покажите алгебраическое устранение неопределённости.", "legacy-kr-2": "Контрольная, вариант 1, №2. Вычислите limₓ→−∞(√(x²+2x+1)−√(x²−4x+1)). Корни — неотрицательные действительные. Эквивалентности и правило Лопиталя не используйте; учитывайте знак x при извлечении √(x²).", "legacy-kr-3": "Контрольная, вариант 1, №3. Вычислите limₓ→3 (∛(x+5)−2)/(x²−2x−3) по области определения дроби. Кубический корень действительный. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-4": "Контрольная, вариант 1, №4. Вычислите двусторонний предел limₓ→0 x·ctg(πx+x²) по области определения котангенса. Углы измеряются в радианах; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-5": "Контрольная, вариант 1, №5. Вычислите limₓ→π/4 (√2−2cos x)/(π−4x) при x≠π/4. Углы измеряются в радианах; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-6": "Контрольная, вариант 1, №6. Вычислите limₓ→+∞((x+3)/(x−2))^(2x+1). При достаточно больших x основание положительно. Эквивалентности и правило Лопиталя не используйте; допускается второй замечательный предел.", "legacy-kr-7": "Контрольная, вариант 1, №7. Вычислите limₓ→2 (log₃x−log₃2)/(x²−4) по x>0, где знаменатель ненулевой. Здесь log₃ — логарифм по основанию 3. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-8": "Контрольная, вариант 1, №8. Используя эквивалентности, вычислите limₓ→0 (e^(2x²)−cos(3x))/(¹⁰√(2x²+10)−¹⁰√10) при x≠0. Оба корня десятой степени неотрицательные действительные; углы — в радианах.", "legacy-kr-9": "Контрольная, вариант 2, №1. Исследуйте двусторонний предел limₓ→−1 (x²−1)/(x³−3x−2) по области определения дроби. Если двустороннего предела нет, укажите оба односторонних предела и их знаки. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-10": "Контрольная, вариант 2, №2. Вычислите limₓ→−∞(∛(x³+x²+x+1)−∛(x³−x²+x−1)). Оба кубических корня действительные. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-11": "Контрольная, вариант 2, №3. Вычислите limₓ→−1 (√(3−x)+2x)/(√(10+x)+3x) по действительной области определения дроби. Квадратные корни неотрицательные; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-12": "Контрольная, вариант 2, №4. Вычислите limₓ→0 sin(7x+x²)/tg(3x+x³) по области определения дроби. Углы измеряются в радианах; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-13": "Контрольная, вариант 2, №5. Вычислите limₓ→π (cos(2x)+cos(3x))/(x−π)² при x≠π. Углы измеряются в радианах; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-14": "Контрольная, вариант 2, №6. Вычислите limₓ→+∞((x²+5)/(x²−2))^(2x²+1). При достаточно больших x основание положительно. Эквивалентности и правило Лопиталя не используйте; допускается второй замечательный предел.", "legacy-kr-15": "Контрольная, вариант 2, №7. Вычислите limₓ→3 (2ˣ−8)/(x²−9) по области определения дроби. Эквивалентности и правило Лопиталя не используйте; допускается следствие второго замечательного предела для aˣ−1.", "legacy-kr-16": "Контрольная, вариант 2, №8. Используя эквивалентности, вычислите limₓ→0(⁷√(3x³+4)−⁷√4)/log₃(sin(x³)+e^(3x³)) по действительной области определения дроби. Корни седьмой степени действительные, log₃ — логарифм по основанию 3, углы — в радианах.", "legacy-kr-17": "Контрольная, вариант 6, №1. Вычислите limₓ→−1 (x³+1)/(x³+3x+4) по области определения дроби. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-18": "Контрольная, вариант 6, №2. Вычислите limₓ→−∞(∛(x³+2x²+x+1)−∛(x³−x²+3x−1)). Оба кубических корня действительные. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-19": "Контрольная, вариант 6, №3. Вычислите limₓ→−2 (√(2−x)+x)/(√(11+x)+1,5x) по действительной области определения дроби. Квадратные корни неотрицательные; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-20": "Контрольная, вариант 6, №4. Вычислите правый предел limₓ→0+ sin(11x+2√x)/tg(5x−3√x). Здесь x>0, квадратный корень неотрицательный, углы — в радианах. Эквивалентности и правило Лопиталя не используйте.", "legacy-kr-21": "Контрольная, вариант 6, №5. Вычислите limₓ→π (cos(3x)−cos(5x))/(π−x)² при x≠π. Углы измеряются в радианах; эквивалентности и правило Лопиталя не используйте.", "legacy-kr-22": "Контрольная, вариант 6, №6. Вычислите limₓ→+∞((x²−5)/(x²+3))^(3x²−1). При достаточно больших x основание положительно. Эквивалентности и правило Лопиталя не используйте; допускается второй замечательный предел.", "legacy-kr-23": "Контрольная, вариант 6, №7. Вычислите limₓ→1 (x^(17/10)−1)/(3x²+2x−5) по x>0 с ненулевым знаменателем. Показатель 1,7 означает точно 17/10. Эквивалентности и правило Лопиталя не используйте.", "extra-4-1": "Пусть A⊂ℝ непусто и имеет конечные точные грани inf A=−3, sup A=5. Для отражённого множества −A={−a:a∈A} найдите inf(−A) и sup(−A) именно в этом порядке.", "extra-4-2": "Даны A=(1,4) и B=[−2,3]. Разность здесь означает A−B={a−b:a∈A,b∈B}, а не удаление элементов B из A. Найдите sup(A−B).", "extra-5-1": "Дано X={1,2,3,…}⊂ℝ. Теорема о существовании действительного sup требует непустоты и ограниченности сверху. Какое из этих условий не выполнено для X и потому не позволяет применить теорему?", "extra-5-2": "Дано непустое множество X={x∈ℝ:x²<2}. Найдите его конечную точную верхнюю грань sup X. То, что неравенство строгое, не означает отсутствия супремума.", "extra-7-1": "Может ли действительная последовательность одновременно удовлетворять условиям x₁=1000 и limₙ→∞ xₙ=2? Никаких дополнительных ограничений на остальные члены не задано; ответ обоснуйте примером или противоречием.", "extra-8-1": "Пусть действительная последовательность xₙ→4 при n→∞. Какая из предложенных оценок обязательно верна для всех n>N при некотором N, независимо от первых членов и от стороны приближения к пределу?", "extra-8-2": "Пусть действительная последовательность xₙ→0. Обязан ли существовать номер N, после которого все xₙ имеют один и тот же строгий знак? В предложенном отрицательном ответе последовательность служит контрпримером, а не дополнительным условием.", "extra-9-1": "Пусть (xₙ) — действительная последовательность, xₙ≥2 для всех n≥1 и существует конечный предел a=limₙ→∞ xₙ. Какое утверждение об a обязательно следует из этих условий для любой такой последовательности?", "extra-10-1": "Пусть действительная последовательность (zₙ) для каждого n≥1 удовлетворяет 2−1/n≤zₙ≤2+3/n. Докажите существование её предела и найдите limₙ→∞ zₙ; других сведений о zₙ нет.", "extra-11-1": "Дана действительная последовательность xₙ=(−1)ⁿn при n≥1. Выполнено ли |xₙ|→+∞, то есть является ли она бесконечно большой по модулю? Существование знакового предела +∞ или −∞ — другой вопрос.", "extra-20-1": "Пусть a — предельная точка действительной области E и f:E→ℝ. Может ли при одном и том же приближении x→a по E∖{a} функция одновременно иметь два различных конечных предела A≠B? Обе предельные величины относятся к одному подходу, а не к разным сторонам.", "extra-20-2": "Пусть f определена в некоторой двусторонней проколотой окрестности 0 и f(x)→0 при x→0. Обязана ли f сохранять один строгий знак во всей достаточно малой проколотой окрестности? Если нет, предложенный пример должен удовлетворять исходному пределу.", "extra-22-1": "При x∈ℝ, x≠1, задано f(x)=(x²−1)/(x−1). В точке 1 назначают значение f(1)=c. Найдите единственное c∈ℝ, при котором доопределённая функция непрерывна в 1.", "extra-23-1": "Пусть g(x)=x²−1 на ℝ и f(t)=1/t при t≠0. Найдите все действительные x, для которых композиция h(x)=f(g(x)) определена и непрерывна. Точки, в которых g(x) не входит в область f, должны быть исключены.", "extra-23-2": "Рассмотрите h(x)=√|x| на всей ℝ; квадратный корень неотрицательный. Непрерывна ли h в x=0? Проверьте области внутренней и внешней функций либо предъявите подходящий радиус δ(ε) в определении непрерывности.", "extra-24-1": "Пусть tg x=sin x/cos x, углы измеряются в радианах. Укажите все действительные x, где тангенс одновременно определён и непрерывен; доопределять его в нулях cos x не требуется.", "extra-27-1": "Для f(x)=x на ℝ требуется проверить критерий Коши при x→0. Пусть ε>0 произвольно. Какая предложенная δ(ε)>0 обеспечивает |f(x)−f(y)|<ε для любых двух аргументов с 0<|x|<δ и 0<|y|<δ?", "extra-30-1": "Рассмотрите f(x)=1/(1+x²) на замкнутом отрезке [−2,3]. Какой предложенный ответ корректно обосновывает ограниченность f на всём этом отрезке и даёт верные общие числовые границы её значений?", "extra-30-2": "Можно ли применить теорему об ограниченности непрерывной функции на замкнутом отрезке к выражению f(x)=1/(x−1) на всём [0,2]? В x=1 отдельное значение не назначается. Проверьте, выполнены ли все условия теоремы.", "extra-31-1": "Дана f(x)=|x−1| на [−1,4]. Найдите её наименьшее и наибольшее значения на всём отрезке; в обосновании укажите точки достижения обоих значений.", "extra-33-1": "Для f(x)=x² на [−2,2] имеем f(−2)=f(2)=4. Существует ли хотя бы одна точка c∈(−2,2) с f(c)=1? При применении теоремы о промежуточных значениях учитывайте минимум и максимум функции на всём отрезке, а не только значения на концах.", "extra-34-1": "Дана f:[1,4]→ℝ, f(x)=2x−3. Найдите множество значений f, то есть область определения обратной функции g, и выразите g(y) через y. В ответе нужны и формула, и точная область определения обратной.", "extra-34-2": "Рассмотрите f:[−1,1]→[0,1], f(x)=x². Существует ли на всём образе [0,1] одна обратная функция g, для которой g(f(x))=x при каждом x∈[−1,1]? Ограничивать исходную область только одной половиной отрезка нельзя.", "legacy-small-3": "Пусть (αₙ),(bₙ) — действительные последовательности, αₙ→0 при n→∞ и |bₙ|≤7 для каждого n≥1. Какое утверждение о пределе произведения αₙbₙ обязательно следует? Сходимость самой последовательности bₙ не предполагается.", "method-38-1": "Докажите по Коши limₓ→2(3x+1)=7. Для произвольного ε>0 выберите δ(ε)>0, обеспечивающую |(3x+1)−7|<ε для всех x∈ℝ с 0<|x−2|<δ.", "method-38-2": "Докажите по Коши limₓ→3 x²=9. Какой предложенный δ(ε)>0 гарантирует |x²−9|<ε для каждого ε>0 и для всех x с 0<|x−3|<δ, одновременно контролируя множитель |x+3|?", "method-38-3": "Для f(x)=1/x, x≠0, докажите по Коши limₓ→2 f(x)=1/2. При произвольном ε>0 выберите радиус δ, который одновременно удерживает x вдали от нуля и обеспечивает |1/x−1/2|<ε при 0<|x−2|<δ.", "method-38-4": "Пусть x₀∈ℝ фиксировано, f(x)=1/(x−x₀)² при x≠x₀. Докажите limₓ→x₀+ f(x)=+∞ по определению: для каждого M>0 выберите δ(M)>0, чтобы 0<x−x₀<δ влекло f(x)>M.", "method-38-5": "Пусть f(x)=2+3/x при x>0. Докажите по определению limₓ→+∞ f(x)=2: для каждого ε>0 выберите положительный порог R(ε), чтобы для всех x>R выполнялось |f(x)−2|<ε.", "method-38-6": "Пусть f(x)=|x|/x при x≠0. Существует ли конечный двусторонний предел f при x→0? Найдите односторонние пределы и оцените предложенный ответ о двустороннем пределе; значение в самой точке 0 не задаётся.", "method-39-1": "Требуется доказать по Гейне limₓ→3 x²=9 для функции f(x)=x² на ℝ. Какое действие достаточно для доказательства: как выбрать последовательность аргументов и какой предел её образов установить? Проверка одной специально выбранной последовательности не заменяет всеобщего условия.", "method-39-2": "Пусть f(x)=(x²−4)/(x−2) при x≠2. Для доказательства limₓ→2 f(x)=4 по Гейне берут произвольную действительную последовательность xₙ→2 с xₙ≠2 для каждого n. Какое предложенное преобразование f(xₙ) законно на этой области?", "method-39-3": "Дано f(x)=|x|/x при x≠0 и две последовательности xₙ=1/n, yₙ=−1/n, n≥1. Какой вывод о двустороннем пределе f при x→0 следует из пределов f(xₙ) и f(yₙ)? Проверяется вывод именно для этой функции.", "method-39-4": "Пусть f(x)=sin(1/x) при x>0, углы измеряются в радианах. Какую пару положительных последовательностей xₙ→0, yₙ→0 можно использовать, чтобы значения f(xₙ),f(yₙ) имели разные пределы и опровергали существование правого предела в 0?", "method-39-5": "Пусть f(x)=√x на [0,+∞), корень неотрицательный. Для доказательства по Гейне limₓ→0+ f(x)=0 берётся произвольная положительная последовательность xₙ→0. Какой предложенный довод доказывает √xₙ→0 для любой такой последовательности?", "method-39-6": "Пусть f(x)=1/x² при x≠0. Для произвольной действительной последовательности xₙ→0 с xₙ≠0 при каждом n какой вывод о f(xₙ) обязателен? Проверьте по определению порога M>0, а не только для положительной xₙ=1/n."};
const EXERCISE_PROMPTS={"1": "Пусть X,Y⊂ℝ — непустые множества, ограниченные сверху. Определим X+Y={x+y:x∈X,y∈Y}. Докажите sup(X+Y)=sup X+sup Y, проверив верхнюю оценку для всех сумм и точность границы с произвольным ε>0.", "2": "Пусть X,Y⊂ℝ — непустые множества, ограниченные снизу, и X+Y={x+y:x∈X,y∈Y}. Докажите inf(X+Y)=inf X+inf Y. В доказательстве должны присутствовать нижняя оценка всех сумм и приближение к ней сверху.", "3": "Пусть X⊂ℝ непусто и ограничено снизу. Для −X={−x:x∈X} докажите sup(−X)=−inf X. Существование конечной inf X следует из условий.", "4": "Пусть X⊂ℝ непусто и ограничено сверху. Для −X={−x:x∈X} докажите inf(−X)=−sup X. Проверьте как оценку, так и её точность.", "5": "Пусть X,Y⊂ℝ непусты и имеют конечные точные верхние грани. Предположим ∀x∈X ∀y∈Y: x≤y. Докажите sup X≤sup Y. Здесь сравниваются все пары элементов двух множеств; условие не означает включения X⊆Y.", "6": "Пусть X,Y⊂ℝ непусты и имеют конечные точные нижние грани. Предположим ∀x∈X ∀y∈Y: x≤y. Докажите inf X≤inf Y. Обозначение порядка множеств означает это попарное неравенство, а не включение.", "7": "Пусть X,Y⊂ℝ непусты и ∀x∈X ∀y∈Y: y≤x. Докажите существование конечных inf X и sup Y и установите неравенство inf X≥sup Y. Воспользуйтесь тем, что любой выбранный элемент одного множества ограничивает другое с нужной стороны.", "8": "Пусть X⊂ℝ непусто и ограничено снизу. Непосредственно из полноты ℝ докажите существование действительного inf X, проверив, что найденное число является нижней границей и не меньше любой другой нижней границы.", "9": "Пусть (xₙ) — действительная последовательность, a∈ℝ. Для каждого ε>0 существует бесконечно много индексов n с |xₙ−a|<ε; значения членов при разных индексах могут совпадать. Обязаны ли из этого следовать сходимость всей последовательности и её ограниченность? Если нет, постройте контрпример.", "10": "Может ли действительная последовательность, неограниченная по модулю, иметь конечную предельную точку a∈ℝ, то есть сходящуюся к a подпоследовательность? Требуется пример или доказательство невозможности; условие |xₙ|→∞ не предполагается.", "11": "Пусть действительная последовательность бесконечно большая по модулю: ∀M>0 ∃N ∀n>N: |xₙ|>M. Может ли у неё существовать подпоследовательность с конечным пределом a∈ℝ? Докажите свой ответ.", "12": "Пусть действительная последовательность имеет ровно одну конечную предельную точку a∈ℝ. Ограниченность последовательности не задана. Обязательно ли xₙ→a? Затем отдельно исследуйте, изменится ли ответ при дополнительном условии ограниченности.", "13": "Пусть k∈ℕ, k≥1, и xₙ→a∈ℝ. Для чётного k дополнительно предположим xₙ≥0 для всех n; тогда a≥0. При нечётном k разрешены любые действительные xₙ и a. Докажите сходимость действительных корней k-й степени: √[k](xₙ)→√[k](a), отдельно разобрав необходимые случаи знака a.", "14": "Для n∈ℕ, n≥1, положим Hₙ=1+1/2+…+1/n. Докажите по критерию Коши, что (Hₙ) не имеет конечного предела. Нужно предъявить фиксированное ε₀>0 и для любого N найти m,n>N, нарушающие |Hₘ−Hₙ|<ε₀.", "15": "На ℝ задана функция Дирихле D(x)=1 при x∈ℚ и D(x)=0 при x∉ℚ. Докажите отсутствие конечного предела D(x) при x→a в каждой точке a∈ℝ, используя плотность рациональных и иррациональных чисел либо определения Коши и Гейне.", "16": "Пусть f(x)=cos(1/x) при x∈ℝ, x≠0, углы измеряются в радианах. Докажите, что в точке 0 не существует ни правого, ни левого предела. Для каждой стороны предъявите допустимые последовательности аргументов с различными пределами значений.", "17": "Пусть n∈ℕ, n≥1, k∈ℕ, k≥2. Докажите непрерывность функций xⁿ, действительного корня √[k](x), sin x, cos x и 1/x в каждой точке их естественной действительной области. Для чётного k корень рассматривается на [0,+∞), в точке 0 — относительно этой области; для 1/x точка a должна быть ненулевой. Углы измеряются в радианах.", "18": "Пусть m,n — положительные целые числа, функции α,β определены при всех достаточно малых x≠0 и при x→0 удовлетворяют α(x)=o(xⁿ), β(x)=o(xᵐ). Докажите α(x)+β(x)=o(x^min(n,m)) и α(x)−β(x)=o(x^min(n,m)).", "19": "Пусть m,n — положительные целые числа, α(x)=o(xⁿ), β(x)=o(xᵐ) при x→0 по общей проколотой области определения. Докажите α(x)β(x)=o(x^(n+m)), явно исследовав отношение к x^(n+m).", "20": "Пусть m,n — положительные целые числа. В некоторой проколотой окрестности 0 определены α,β, причём α(x)≠0, α(x)=o(xᵐ) и β(x)=o(α(x)ⁿ) при x→0. Докажите β(x)=o(x^(mn)). Все отношения из определения o-малого берутся на указанной области.", "21": "Пусть α(x) определена в проколотой окрестности a∈ℝ, α(x)→0 при x→a и α(x)≠0 там, где вычисляется отношение. Углы измеряются в радианах. Докажите limₓ→a sin(α(x))/α(x)=1 и обоснуйте допустимость подстановки в первый замечательный предел.", "22": "Пусть α(x)→0 при x→a∈ℝ. Отношение и степень рассматриваются для достаточно близких x≠a с α(x)≠0 и 1+α(x)>0. Докажите limₓ→a(1+α(x))^(1/α(x))=e и обоснуйте замену переменной во втором замечательном пределе.", "23": "Пусть действительная последовательность монотонна и неограниченна по модулю. Докажите |xₙ|→+∞. Разберите оба возможных случая: неубывающую последовательность без верхней границы и невозрастающую без нижней границы; укажите соответствующий знаковый бесконечный предел.", "24": "Пусть действительная последовательность (xₙ) неограниченна по модулю. Постройте строго возрастающие натуральные индексы nₖ так, чтобы |xₙₖ|→+∞. Монотонность исходной последовательности и постоянство знака её членов не предполагаются.", "25": "Дана f(x)=sin(1/x), x>0; углы измеряются в радианах. Для E₁=(0,1) и E₂=[1/2,1] найдите точные модули непрерывности ω_f(δ;E)=sup{|f(x)−f(y)|:x,y∈E, |x−y|<δ}, δ>0, и определите равномерную непрерывность на каждом множестве. Для E₂ допускается точная формула через максимум непрерывной функции на отрезке; одну лишь верхнюю оценку нельзя выдавать за точный модуль.", "26": "Дана f(x)=x². Для E₁=(0,1) и E₂=[−2,1] найдите ω_f(δ;E)=sup{|f(x)−f(y)|:x,y∈E, |x−y|<δ} при всех δ>0 и исследуйте её предел при δ→0+. В определении расстояние строго меньше δ, поэтому достижение супремума на граничной паре не предполагается."};
const GUARANTEED_QUESTIONS=new Set(["core-12", "core-17", "core-20", "core-33", "core-39", "core-6", "core-8", "core-9", "extra-10-1", "extra-20-1", "extra-20-2", "extra-23-2", "extra-24-1", "extra-30-1", "extra-33-1", "extra-34-2", "extra-7-1", "extra-8-1", "extra-8-2", "extra-9-1", "legacy-compactness-1", "legacy-compactness-3", "legacy-compactness-4", "legacy-compactness-5", "legacy-compactness-6", "legacy-compactness-7", "legacy-compactness-8", "legacy-continuity-2", "legacy-continuity-3", "legacy-continuity-6", "legacy-continuity-7", "legacy-continuity-8", "legacy-functionlim-4", "legacy-infinite-4", "legacy-monotone-1", "legacy-monotone-4", "legacy-monotone-6", "legacy-monotone-7", "legacy-onesided-2", "legacy-onesided-5", "legacy-onesided-7", "legacy-onesided-8", "legacy-seq-5", "legacy-seq-8", "legacy-seqops-5", "legacy-seqops-6", "legacy-seqops-8", "legacy-sets-8", "legacy-small-3", "legacy-uniform-1", "legacy-uniform-3", "legacy-uniform-5", "legacy-uniform-6", "legacy-uniform-8", "method-39-1", "method-39-3", "method-39-5", "method-39-6"]);
function questionEvaluationPrompt(q){return q.questionKind==='guarantee'?'Обязательно ли это утверждение следует из всех условий задачи? Возможности отдельного примера недостаточно.':'Полностью ли предложенный ответ соответствует условию и поставленному вопросу?';}
function questionVerdictMeaning(q,truth){return q.questionKind==='guarantee'?(truth?'Это утверждение обязательно следует из условий.':'Условия не гарантируют этот вывод. Он может быть верен для отдельного примера, но не обязан выполняться всегда.'):(truth?'Предложенный ответ верен для поставленной задачи.':'Предложенный ответ не соответствует поставленной задаче.');}
function prepareTrainingQuestion(q){let definition=QUESTION_PROMPTS[q.id];if(!definition)return q;let out={...q,question:definition,questionKind:GUARANTEED_QUESTIONS.has(q.id)?'guarantee':'task'};if(q.id==='legacy-seq-4')out.options=q.options.map(text=>text==='не имеет предела; имеет две предельные точки'?'Не имеет конечного предела; её конечные предельные точки — −1 и 1':text);if(q.id==='core-9')out.options=['Обязательно 0≤a≤1','Обязательно 0<a<1','Обязательно a=1/2'];if(q.id==='core-16')out.options=['Все положительные общие точки исключаются условием x<1/n, а 0 не входит ни в один интервал',...q.options.slice(1)];if(q.id==='extra-23-2')out.formula=String.raw`h(x)=\sqrt{|x|},\qquad x\in\mathbb R.`;if(q.id==='extra-34-1')out.formula=String.raw`f(x)=2x-3,\qquad x\in[1,4].`;return out;}
function syncCompleteQuestions(){if(typeof COURSE!=='undefined')for(let t of COURSE){let q=prepareTrainingQuestion({id:'core-'+t.id,question:t.question,options:t.options});t.question=q.question;t.options=q.options;t.questionKind=q.questionKind;if(typeof DETAILED_SOLUTIONS!=='undefined'&&DETAILED_SOLUTIONS.practice[t.id])t.solution=DETAILED_SOLUTIONS.practice[t.id].map(s=>s.title+'. '+s.text);}
if(typeof EXERCISES!=='undefined')EXERCISES.forEach((e,i)=>{e[1]=EXERCISE_PROMPTS[i+1]||e[1]});
if(typeof topics!=='undefined'&&Array.isArray(topics))for(let t of topics)t.qs.forEach((q,i)=>{let def=prepareTrainingQuestion({id:'legacy-'+t.id+'-'+(i+1),question:q[0],options:q[1]});q[0]=def.question;q[1]=def.options;q.questionKind=def.questionKind});
if(typeof METHOD_LESSONS!=='undefined'){for(let id of [38,39])METHOD_LESSONS[id].examples.forEach((e,i)=>{let prompt=QUESTION_PROMPTS['method-'+id+'-'+(i+1)];e.task=prompt+' '+(id===38?'Запишите определение по Коши символами и словами, его отрицание и обоснуйте каждый выбранный параметр.':'Запишите условие Гейне и обоснуйте принадлежность аргументов области определения, их приближение и пределы значений.');});METHOD_LESSONS[38].examples[5].task='Пусть f(x)=|x|/x при x≠0. Сначала по отрицанию определения Коши докажите, что число 1 не является её двусторонним пределом при x→0. Затем отдельным рассуждением докажите, что никакого конечного двустороннего предела не существует. Найдите односторонние пределы и поясните схему.';}}
syncCompleteQuestions();
function solutionStepRole(step){if(step.role==='counterexample'||/контрпример|например|для примера/i.test(step.text))return 'Пример для обоснования, не дополнительное условие';if(/^(?:берём|возьмём|выберем|положим|зададим)/i.test(step.text))return 'Вспомогательный выбор в доказательстве';return '';}
function questionGivenPanel(q){return `<div class="solution-given"><strong>Условие и требуемый результат</strong><p>${esc(q.question)}</p></div>`;}
